<script setup lang="ts">
import GlobalDropdown from '../../components/GlobalDropdown.vue'
import type { SessionUser } from '../../stores/session'
defineProps<{ exceptionDetail: Record<string, any> | null; currentUser: SessionUser | null; exceptionOperators: {id: string; full_name: string}[]; evidenceFile: File | null }>()
const emit = defineEmits<{ openBatch: []; assign: []; propose: []; downloadEvidence: [action: Record<string, any>]; addNote: []; file: [event: Event]; chooseFile: []; uploadEvidence: [] }>()
const operatorSearchModel = defineModel<string>('operatorSearch', { required: true })
const assignmentTargetModel = defineModel<string>('assignmentTarget', { required: true })
const investigationNoteModel = defineModel<string>('investigationNote', { required: true })
function formatDate(value?: string) { return value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeZone: 'Asia/Jakarta' }).format(new Date(value)) : '—' }
function money(value?: number | null) { return value == null ? '—' : new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value) }
</script>

<template>
        <section class="detail-page exception-detail-page">
          <div class="detail-title"><div><div class="title-line"><h2>{{ exceptionDetail?.reference_id || 'Exception' }}</h2><span class="badge warning">{{ exceptionDetail?.type || '—' }}</span></div><p>{{ exceptionDetail?.batch_no }} <span>·</span> {{ exceptionDetail?.state }} <span>·</span> PIC: {{ exceptionDetail?.assignee_name || 'Belum ditugaskan' }}</p></div><button v-if="exceptionDetail?.batch_id" class="button secondary" data-loading @click="emit('openBatch')">Lihat batch</button><div v-if="currentUser?.role === 'OPERATOR' && exceptionDetail?.can_assign_others && ['OPEN','INVESTIGATING'].includes(exceptionDetail?.state)" class="exception-assignment"><input v-model="operatorSearchModel" class="form-control" aria-label="Cari operator" placeholder="Cari nama Operator" /><GlobalDropdown v-model="assignmentTargetModel" class="form-control" aria-label="Pilih penanggung jawab"><option :value="currentUser?.id || ''">Saya · {{ currentUser?.full_name }}</option><option v-for="operator in exceptionOperators.filter(item => item.id !== currentUser?.id)" :key="operator.id" :value="operator.id">{{ operator.full_name }}</option></GlobalDropdown><button class="button secondary" :disabled="!assignmentTargetModel" @click="emit('assign')">Tugaskan</button></div><button v-if="exceptionDetail?.type === 'DATE_VARIANCE' && currentUser?.role === 'OPERATOR' && ['OPEN','INVESTIGATING'].includes(exceptionDetail?.state)" class="button primary" data-loading @click="emit('propose')">Ajukan Manual Match</button></div>
          <div class="comparison-grid"><article class="panel"><div class="panel-heading"><div><h2>Data Internal</h2><p>{{ exceptionDetail?.internal?.source_type || 'INTERNAL' }}</p></div></div><div class="data-pair"><span>Reference ID</span><b>{{ exceptionDetail?.internal?.reference_id || '—' }}</b></div><div class="data-pair"><span>Tanggal</span><b>{{ formatDate(exceptionDetail?.internal?.date) }}</b></div><div class="data-pair"><span>Arah</span><b>{{ exceptionDetail?.internal?.direction || '—' }}</b></div><div class="data-pair"><span>Nominal</span><b>{{ money(exceptionDetail?.internal?.amount_rupiah) }}</b></div></article><article class="panel"><div class="panel-heading"><div><h2>Data Bank</h2><p>{{ exceptionDetail?.bank?.source_type || 'BANK' }}</p></div></div><div class="data-pair"><span>Reference ID</span><b>{{ exceptionDetail?.bank?.reference_id || '—' }}</b></div><div class="data-pair"><span>Tanggal</span><b>{{ formatDate(exceptionDetail?.bank?.date) }}</b></div><div class="data-pair"><span>Arah</span><b>{{ exceptionDetail?.bank?.direction || '—' }}</b></div><div class="data-pair mismatch"><span>Nominal</span><b>{{ money(exceptionDetail?.bank?.amount_rupiah) }}</b></div></article></div><article v-if="exceptionDetail?.type === 'AMBIGUOUS_MATCH'" class="panel ambiguity-panel"><h3>Transaksi dengan reference yang sama</h3><p>Reference ini muncul lebih dari sekali. Pilihannya perlu diperiksa dan sumber diperbaiki sebelum batch diajukan.</p><div class="candidate-table-wrap"><table class="candidate-table"><thead><tr><th>Sumber</th><th>Referensi</th><th>Tanggal</th><th>Arah</th><th>Nominal</th><th>Mata uang</th></tr></thead><tbody><tr v-for="candidate in exceptionDetail.candidates || []" :key="candidate.id"><td>{{ candidate.source_type }}</td><td>{{ candidate.reference_id }}</td><td>{{ formatDate(candidate.date) }}</td><td>{{ candidate.direction }}</td><td>{{ money(candidate.amount_rupiah) }}</td><td>{{ candidate.currency }}</td></tr></tbody></table></div><p v-if="!exceptionDetail.candidates?.length">Tidak ada kandidat yang tersedia.</p></article>
          <article class="panel timeline-panel"><div class="panel-heading"><div><h2>Riwayat Pemeriksaan</h2><p>Catatan dan assignment exception</p></div></div><div class="timeline"><div v-for="action in exceptionDetail?.actions || []" :key="action.id"><i></i><span><b>{{ action.action_type }} · {{ action.actor_name }}</b><small>{{ action.note || 'Tidak ada catatan' }} · {{ formatDate(action.created_at) }}</small><button v-if="action.has_evidence" class="link-button" @click="emit('downloadEvidence', action)">Unduh {{ action.file_name || 'evidence' }}</button></span></div><p v-if="!exceptionDetail?.actions?.length">Belum ada tindakan.</p></div><label v-if="currentUser?.role === 'OPERATOR' && ['OPEN','INVESTIGATING','PENDING_ACTION_APPROVAL'].includes(exceptionDetail?.state)" class="field-label">Catatan investigasi<textarea v-model="investigationNoteModel" class="form-control" rows="2" placeholder="Catatan untuk audit trail"></textarea></label><button v-if="currentUser?.role === 'OPERATOR' && ['OPEN','INVESTIGATING','PENDING_ACTION_APPROVAL'].includes(exceptionDetail?.state)" class="button secondary" :disabled="!investigationNoteModel.trim()" @click="emit('addNote')">Simpan Catatan</button><div v-if="currentUser?.role === 'OPERATOR' && ['OPEN','INVESTIGATING','PENDING_ACTION_APPROVAL'].includes(exceptionDetail?.state)" class="evidence-upload"><input id="exception-evidence-input" class="hidden-input" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,application/pdf,image/png,image/jpeg,text/plain" @change="emit('file', $event)" /><span>{{ evidenceFile?.name || 'PDF, PNG, JPEG, TXT · maks. 5 MB' }}</span><button class="button secondary" @click="emit('chooseFile')">Pilih Evidence</button><button class="button primary" :disabled="!evidenceFile" @click="emit('uploadEvidence')">Unggah</button></div></article>
        </section>

</template>
